// periop.js: the patients of the day, where they wait, and what happens when one is taken to the operating room.
//
// Pre-op holding has four bays. Each holds one of the app's own mock patients as a person on a stretcher, and the bay's
// display reads from that patient's chart. The schedule board lists all of them. At a bay you open the Student Workstation
// (the classic app's own page: chart review, interview, care plan, Booth's grade) without leaving the building, and when the
// plan is in you take the patient to the operating room.
//
// In the operating room the case runs on the app's engine (js/cases.js). What you do is a hand on something: the monitor
// leads, the mask, a syringe you drew up and labelled, the blade, the tube, the ventilator, the vaporizer. You can work from
// the step list or from memory, saying or typing each thing you do. The room's monitor and ventilator display show the engine
// (js/clinical.js). The steps are the program's own rubrics, in their own words. Nothing here decides what is clinically
// right: the engine and the rubrics do, and the record says which of them scored what.
import * as THREE from 'three';
import { loadSchedule, loadChart, planStatus, pointWorkstationAt, createCase, DRUGS, DRUG_CLASS, ACTIONS, PHASES } from './cases.js';
import { recordAttempt } from './save.js';
import { sfx, isMuted } from './audio.js';
import { drawTexture } from './brand.js';

