const SEQ = { standard: 'Standard IV induction', rsi: 'Rapid sequence induction', emergence: 'Emergence' };
const BRIEF = {
  standard: 'The patient is on the table, awake, with a working IV. Take them from the first monitor to incision. When the surgeon is closing, take them through emergence, extubation and handover.',
  rsi: 'The patient is on the table, awake, with a working IV, and is at risk of aspiration. Take them from the first monitor to incision by rapid sequence. When the surgeon is closing, take them through emergence, extubation and handover.',
  emergence: 'The case is handed to you at the end of surgery: the patient is intubated, ventilated and on an inhaled agent. Take them through emergence, extubation and handover.' };
const who = (e) => e.label.replace(/^CN Rubric\s*·\s*/, ''), mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
